          "人間の意思決定と制度を証拠で調べるため、経済学は社会科学である。Microeconomicsはバス運賃が乗客に与える影響を、macroeconomicsは経済全体の失業の変化を問う。人の反応は異なるため、経済予測は物理法則ではなく条件付きである。",
