          "一日パン個数をQd=100−10P、Qs=20+10Pとする。3ドルでは需要70・供給50で不足20が競り上げや値上げを促す。5ドルでは供給70・需要50で余剰20が値下げを促す。4ドルでは双方60を計画するのでその圧力はない。",
          "価格は相対的希少性と潜在利潤を伝え、生産拡大や節約の誘因を与え、買う意思と能力を持つ者へ財を配分する。支出を得る活動へ資源を向けるが、購買力を反映するため公平性は保証しない。供給一定の需要増は通常均衡価格・数量を上げ、供給増は通常価格を下げ数量を上げる。"
