          "誰の活動の波及かを区別する。工場煙は生産中に住民を害する（MSC>MPC）。夜の大音量音楽は消費中に近隣を害する（MSB<MPB）。養蜂は生産中に他の農家へ受粉をもたらす（本課の費用側の表現でMSC<MPC）。予防接種は消費中に他者の感染リスクを下げる（MSB>MPB）。購入者の支払価格自体は取引の一部であり外部費用ではない。",
          "費用側の図は縦軸に一単位の費用・便益、横軸に期間当たり産出を置く。負の生産外部性ではMSCをMPCの上、MSB=MPBとし、私的交点は社会的交点の右にくる。負の消費外部性ではMSBをMPBの下、MSC=MPCとする。正の生産ではMSC<MPC、正の消費ではMSB>MPBで、私的産出は社会最適より少ない。"
