          "利潤最大化にはMR>MCの間増産し、次単位の費用が追加収入を超える所で止める。滑らかな曲線ではMCが下からMRを横切るMR=MCを選び、実行可能な端点も確認する。複数交点や損失時の操業停止選択で結果が変わるため、MC=MRだけでは不十分。",
          "短期には一部投入が固定。競争企業は収入が可変費用を賄い固定費用の一部に貢献すれば損失でも操業を続け得るが、長期残存には全費用を賄う必要がある。競争下の異常利潤で参入が進むと市場供給増・価格低下、損失での退出は逆を生む。自由参入で同等企業なら長期均衡はnormal profitとP=MCへ向かい、abnormal profitは保証されない。"
