          "Natural monopolyは一企業が複数企業より低い平均費用で対象市場全体を供給できる場合で、巨大固定費用と平均費用低下を伴う設備によく見られる。限界費用価格では収入が総費用を下回り得るため、規制は価格だけでなく資金と誘因を考える。規模の経済や研究予算は低費用・革新を支えるが、保護は改善圧力を弱め得る。",
